#include <bits/stdc++.h>
using namespace std;
int EulerPhi(int n)
{
    int ans = n;
    for (int p = 2; 1LL * p * p <= n; p++) {
        if (n % p == 0) {
            ans = ans / p * (p - 1);
            while (n % p == 0) n /= p;
        }
    }
    if (n > 1) ans = ans / n * (n - 1);
    return ans;
}

