#include <bits/stdc++.h>
using namespace std;
const int inf = 1e7;
const int n = 1e3;
vector<pair<int, int>> g[n];
// { node, cost }

void dijkstra(int source, int nodes)
{
    vector<int> distance(n, inf);
    vector<bool> visited(n, 0);
    set<pair<int, int>> st;
    // { cost, node } : cost আগে থাকে বলে সবচেয়ে কম cost টাই আগে আসে
    st.insert({0, source});
    distance[source] = 0;
    while (!st.empty())
    {
        auto node = *st.begin();
        int parent_node = node.second;
        int parent_node_cost = node.first;
        st.erase(st.begin());
        if (visited[parent_node]) continue;
        visited[parent_node] = 1;
        for (auto child : g[parent_node])
        {
            int child_node = child.first;
            int edge_cost = child.second;
            // Relaxation
            if ((parent_node_cost + edge_cost) < distance[child_node])
            {
                distance[child_node] = (parent_node_cost + edge_cost);
                st.insert({distance[child_node], child_node});
            }
        }
    }
    cout << "Node\tDistance from " << source << endl;
    for (int i = 0; i <= nodes; i++)
        if (distance[i] != inf)
            cout << i << "\t" << distance[i] << endl;
}

int main()
{
    int node, edge, source;
    cin >> node >> edge;
    for (int i = 0; i < edge; i++)
    {
        int u, v, cost;
        cin >> u >> v >> cost;
        g[u].push_back({v, cost});
        g[v].push_back({u, cost});
    }
    cin >> source;
    dijkstra(source, node);
    return 0;
}

#include <bits/stdc++.h>
using namespace std;
const int mx = 1e5 + 10;
vector<int> parent(mx);
vector<int> set_size(mx);

void make(int v)
{
    parent[v] = v;
    set_size[v] = 1;
}

int find(int v)
{
    if (v == parent[v]) return v;
    // path compression
    return parent[v] = find(parent[v]);
}

void union_sets(int a, int b)
{
    a = find(a);
    b = find(b);
    if (a != b)
    {
        // Union by size
        if (set_size[a] < set_size[b]) swap(a, b);
        parent[b] = a;
        set_size[a] += set_size[b];
    }
}

int main()
{
    int n, q;
    cin >> n >> q;
    for (int i = 1; i <= n; i++) make(i);
    while (q--)
    {
        int u, v;
        cin >> u >> v;
        union_sets(u, v);
    }
    int connected_components = 0;
    for (int i = 1; i <= n; i++)
        if (find(i) == i) connected_components++;
    cout << connected_components;
    return 0;
}

